import yaml

def extract_person_record(text):
    try:
        # Split the text into individual records
        records = text.splitlines()
        if len(records) == 0:
            return None
        return {
            "record": records[0],
        }
    except Exception as e:
        print(f"Error extracting record: {e}")
        return None

# Example usage:
text = "Ada Hopper (68): residence 7 Nassau St, Paris. The postcode is 08540. Contact: ada.hopper@example.com. Interests: cryptography, networking."
person_record = extract_person_record(text)
print(person_record)
